import{o as a,c as e,a0 as n}from"./chunks/framework.L_oL6aia.js";const l=JSON.parse('{"title":"Vintage Tuner Stompbox: ユーザーマニュアル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/tuner-pedal.md","filePath":"ja/tuner-pedal.md"}'),r={name:"ja/tuner-pedal.md"},d=Object.assign(r,{setup(s){return(o,t)=>(a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="vintage-tuner-stompbox-ユーザーマニュアル" tabindex="-1">Vintage Tuner Stompbox: ユーザーマニュアル <a class="header-anchor" href="#vintage-tuner-stompbox-ユーザーマニュアル" aria-label="Permalink to &quot;Vintage Tuner Stompbox: ユーザーマニュアル&quot;">​</a></h1><p><strong>バージョン 1.0.1 · Stompbox シリーズ #02 · ギター＆ベース用アナログ・クロマチックチューナー</strong><br><em>開発：Main St Audio Labs · オープンソースDSPエンジン（MITライセンス）</em></p><img src="/TunerPedal.png" alt="Vintage Tuner Stompbox GUI" style="max-height:380px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:8px;"><div style="display:flex;gap:0.75rem;justify-content:center;flex-wrap:wrap;margin:1.25rem 0 1.75rem 0;"><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/vintage-tuner-v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:240px;padding:0.6rem 1.4rem;text-decoration:none;">プラグインをダウンロード (無料 v1.0.1) ⬇️</a><a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" class="rock-btn rock-btn-secondary" style="display:inline-flex;align-items:center;justify-content:center;min-width:200px;padding:0.6rem 1.2rem;text-decoration:none;">GitHubでDSPエンジンを見る (MIT) 🐙</a></div><hr><h2 id="_1-🌟-ステージとスタジオのために設計" tabindex="-1">1. 🌟 ステージとスタジオのために設計 <a class="header-anchor" href="#_1-🌟-ステージとスタジオのために設計" aria-label="Permalink to &quot;1. 🌟 ステージとスタジオのために設計&quot;">​</a></h2><p><strong>Vintage Tuner Stompbox</strong> は、往年のアナログ針式チューナーが持つ視覚的な温かみと滑らかな弾道追従性を、DAWのミックス環境やライブステージへと直接もたらします。</p><p>フォトリアリスティックなレトロ筐体と <strong>Main St Audio Labs</strong> が独自に最適化したDSPにより、画面のチラつきや不自然なオクターブ飛び、微細なジッターを徹底的に抑制。ペグを回す手に吸い付くような自然な針の動きを実現し、アコースティックギター、エレキギター、ドロップチューニング、5弦ベースに至るまで確実に対応します。</p><hr><h2 id="_2-⚡-全トラックに挿せる-真の-0-0-cpu-負荷設計" tabindex="-1">2. ⚡ 全トラックに挿せる：真の 0.0% CPU 負荷設計 <a class="header-anchor" href="#_2-⚡-全トラックに挿せる-真の-0-0-cpu-負荷設計" aria-label="Permalink to &quot;2. ⚡ 全トラックに挿せる：真の 0.0% CPU 負荷設計&quot;">​</a></h2><p>Vintage Tuner Stompbox の最大の特長は、<strong>True Zero-CPU パススルー構造</strong>です：</p><ul><li><strong>エディタを閉じると CPU 0.0%:</strong> DAW上でプラグイン画面を閉じるか、<code>POWER</code> スイッチをオフにすると、数学的ピッチ解析スレッドが即座に完全休止。オーディオ信号を一切の遅延・劣化なくクリーンにパススルーし、CPUリソースを1サイクルも消費しません。</li><li><strong>セッションの全トラックに常駐可能:</strong> プロジェクト内の<strong>すべてのギターやベースのトラックに挿しっぱなし</strong>にしておいても、CPUパフォーマンスを圧迫しません。</li><li><strong>安心のオートアンミュート機能:</strong> <code>MUTE</code> 状態でチューニングした後に画面を閉じて演奏やミックスに戻っても、自動的にミュートが解除されるため、うっかり音が出ないトラブルを防ぎます。</li></ul><hr><h2 id="_3-🎯-ギター-ベース用デュアルピッチdspエンジン-オープンソース" tabindex="-1">3. 🎯 ギター＆ベース用デュアルピッチDSPエンジン（オープンソース） <a class="header-anchor" href="#_3-🎯-ギター-ベース用デュアルピッチdspエンジン-オープンソース" aria-label="Permalink to &quot;3. 🎯 ギター＆ベース用デュアルピッチDSPエンジン（オープンソース）&quot;">​</a></h2><p>ピッチ検出のコアエンジンは、GitHub上に <strong>MITライセンス</strong> で一般公開されている当ラボの数学的ライブラリ（<a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" rel="noreferrer">pitch-detector-tuner</a>）によって駆動されています：</p><h3 id="🔀-リアルタイムで切り替え可能な2つのモード" tabindex="-1">🔀 リアルタイムで切り替え可能な2つのモード： <a class="header-anchor" href="#🔀-リアルタイムで切り替え可能な2つのモード" aria-label="Permalink to &quot;🔀 リアルタイムで切り替え可能な2つのモード：&quot;">​</a></h3><ul><li><strong>MPM モード (McLeod Pitch Method):</strong> エレキギターおよびアコースティックギターに最適化。ピッキング直後のアタック音を瞬時に捉え、素早い単音弾きやコードストローク後の判定も高速です。</li><li><strong>YIN モード (De Cheveigné &amp; Kawahara):</strong> エレキベース（4弦・5弦）、7/8弦ギター、およびドロップチューニング（<em>Drop D, Drop C 等</em>）に特化。<strong>$B_0$ (ローB / 30.87 Hz・25 Hz)</strong> の超低域まで揺るぎない安定感でトラッキングします。</li></ul><h3 id="🛡️-滑らかで音楽的な弾道制御" tabindex="-1">🛡️ 滑らかで音楽的な弾道制御： <a class="header-anchor" href="#🛡️-滑らかで音楽的な弾道制御" aria-label="Permalink to &quot;🛡️ 滑らかで音楽的な弾道制御：&quot;">​</a></h3><ul><li><strong>アンチジッター指数平滑化:</strong> 独自調整されたセンター不感帯（$\\pm 0.6\\text{ セント}$）と指数平滑化フィルターにより、目障りな微細な針の震えを排除。</li><li><strong>ディケイ・ホールド機能 (~0.6秒):</strong> 弦の振動が減衰しても、直前の測定値を一時保持してからゆっくりと中央へ戻るため、視認性が抜群です。</li><li><strong>ダイナミックAGC (+41 dB ブースト):</strong> 出力の弱いヴィンテージのシングルコイルや減衰しかけたロングトーンも最大 $+41\\text{ dB}$（約120倍）まで自動増幅して確実に捉えます。</li><li><strong>インテリジェント Mono-to-Stereo ルーティング:</strong> オーディオインターフェースの Input 1（モノラル）からの入力を、ヘッドフォンやモニターの左右両チャンネルへ自動分配します。</li></ul><hr><h2 id="_4-🎛️-コントロール・ガイド" tabindex="-1">4. 🎛️ コントロール・ガイド <a class="header-anchor" href="#_4-🎛️-コントロール・ガイド" aria-label="Permalink to &quot;4. 🎛️ コントロール・ガイド&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------------+</span></span>
<span class="line"><span>|                      [ ANALOG VU METER ]                    |</span></span>
<span class="line"><span>|                 b FLAT     [-50 .. 0 .. +50]     SHARP #    |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   [ MODE ]               [ NOTE DISPLAY ]         [ A4 REF ]|</span></span>
<span class="line"><span>|   MPM / YIN                E2 · 82.4 Hz           440 Hz    |</span></span>
<span class="line"><span>|                            -0.5 cents                       |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   [ MUTE ]                                        [ POWER ] |</span></span>
<span class="line"><span>|   ON / OFF                                        ON / OFF  |</span></span>
<span class="line"><span>+-------------------------------------------------------------+</span></span></code></pre></div><ul><li><strong>NEEDLE VU METER:</strong> <code>-50</code> から <code>+50 セント</code> の偏差を高精度に表示。合致ゾーン（$\\pm 3\\text{ セント}$）に収まると中央が鮮やかなライムグリーンに点灯します。</li><li><strong>MODE (MPM / YIN):</strong> ギター向け（MPM）とベース／ドロップ向け（YIN）をワンクリックで切り替えます。</li><li><strong>A4 REFERENCE (432 Hz 〜 448 Hz):</strong> 基準ピッチを設定。<strong>ダブルクリック</strong>で標準の <strong>440.0 Hz</strong> にリセットされます。</li><li><strong>MUTE (サイレントチューニング):</strong> 出力を完全ミュートし、ステージやレコーディング中に無音でチューニングできます。</li><li><strong>POWER:</strong> マスター電源スイッチ。OFF時は針が休止し、ピュアなバイパス状態になります（CPU 0%）。</li><li><strong>カスタムスキンドラッグ＆ドロップ:</strong> 任意の <code>.png</code> または <code>.jpg</code> 画像をプラグイン上にドラッグ＆ドロップして外観をカスタマイズできます。</li></ul><hr><h2 id="_5-💡-おすすめの配置とプロのスタジオtips" tabindex="-1">5. 💡 おすすめの配置とプロのスタジオTips <a class="header-anchor" href="#_5-💡-おすすめの配置とプロのスタジオtips" aria-label="Permalink to &quot;5. 💡 おすすめの配置とプロのスタジオTips&quot;">​</a></h2><h3 id="🥇-プラグインチェーンの必ず「スロット-01-最前段-」に配置" tabindex="-1">🥇 プラグインチェーンの必ず「スロット #01（最前段）」に配置 <a class="header-anchor" href="#🥇-プラグインチェーンの必ず「スロット-01-最前段-」に配置" aria-label="Permalink to &quot;🥇 プラグインチェーンの必ず「スロット #01（最前段）」に配置&quot;">​</a></h3><ul><li><strong>原音そのままのピュア信号を入力:</strong> ピッチ検出には、エフェクトを通る前のインターフェース直結のクリーンなDI信号が必要です。</li><li><strong>避けるべき前段エフェクト:</strong><ul><li><strong>歪み・ファズ:</strong> 倍音が増えすぎて基音がマスキングされます。</li><li><strong>コーラス・フェイザー・ビブラート:</strong> ピッチが揺れるため、針がLFOに合わせて振れてしまいます。</li><li><strong>ディレイ・リバーブ:</strong> 前の音の残響と現在の音が混ざってしまいます。</li></ul></li><li><strong>クリーンなステージミュート:</strong> 最前段で <code>MUTE</code> することで、後段のハイゲインアンプにノイズが送られず、曲間を完全な静寂に保てます。</li></ul><h3 id="🎸-高速で正確に合わせるための演奏テクニック" tabindex="-1">🎸 高速で正確に合わせるための演奏テクニック： <a class="header-anchor" href="#🎸-高速で正確に合わせるための演奏テクニック" aria-label="Permalink to &quot;🎸 高速で正確に合わせるための演奏テクニック：&quot;">​</a></h3><ul><li><strong>フロント（ネック）ピックアップを使用:</strong> リアに比べて基音エネルギーが強く、倍音のギラつきが少ないため、アルゴリズムが瞬時にロックします。トーンノブを少し絞るのも効果的です。</li><li><strong>一定の力で優しくピッキング:</strong> 弦を強く叩きつけると、弦の瞬間的な張力増加によりピッチが一時的にシャープ（高め）に振れてしまいます。12フレット付近を親指またはピックで優しく弾くのがベストです。</li><li><strong>5弦ベース（Low-B）の場合:</strong> <strong>YIN</strong> モードを選択してください。12フレットのナチュラルハーモニクスを弾くことで、さらに一瞬で針を安定させることができます。</li></ul><hr><h2 id="_6-🔬-技術仕様-dsp設計" tabindex="-1">6. 🔬 技術仕様＆DSP設計 <a class="header-anchor" href="#_6-🔬-技術仕様-dsp設計" aria-label="Permalink to &quot;6. 🔬 技術仕様＆DSP設計&quot;">​</a></h2><p>C++ / JUCE を用いて、妥協のないリアルタイム性能基準で開発されています：</p><ul><li><strong>非同期オーディオ構造:</strong> リアルタイムオーディオ処理は <code>&lt;0.5 マイクロ秒</code> で完了し、ロックフリーのリングバッファ（16,384サンプル）へ転送。重い自己相関演算は10msごと（約100 FPS）に別スレッドで非同期実行されるため、<strong>音切れやクリックノイズが絶対に発生しません</strong>。</li><li><strong>動的メモリ確保（Heap Allocation）ゼロ:</strong> すべてのバッファメモリは <code>prepareToPlay()</code> で事前確保されます。</li><li><strong>デノーマル数対策 (<code>ScopedNoDenormals</code>):</strong> 無音時のCPUスパイクを防止。</li><li><strong>オープンソースリポジトリ:</strong><br> 👉 <a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" rel="noreferrer">https://github.com/mainstaudiolabs/pitch-detector-tuner</a></li></ul><hr><h2 id="_7-💻-対応環境-ダウンロード" tabindex="-1">7. 💻 対応環境＆ダウンロード <a class="header-anchor" href="#_7-💻-対応環境-ダウンロード" aria-label="Permalink to &quot;7. 💻 対応環境＆ダウンロード&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">OS</th><th style="text-align:left;">フォーマット</th><th style="text-align:left;">要件</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;">VST3 (64-bit), Standalone (<code>.exe</code>)</td><td style="text-align:left;">Windows 10 / 11 (64-bit)</td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;">VST3, AU (<code>.component</code>), Standalone (<code>.app</code>)</td><td style="text-align:left;">macOS 10.13+ (Universal: M1/M2/M3/M4 &amp; Intel)</td></tr><tr><td style="text-align:left;"><strong>Linux</strong></td><td style="text-align:left;">VST3 (64-bit), Standalone binary</td><td style="text-align:left;">Ubuntu 22.04+ または互換 64-bit ディストリビューション</td></tr></tbody></table><div style="margin:1.5rem 0;text-align:center;"><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/vintage-tuner-v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:250px;padding:0.65rem 1.6rem;text-decoration:none;font-size:1rem;">Vintage Tuner Stompbox をダウンロード (無料) ⬇️</a></div><hr><h2 id="_8-📄-ライセンス" tabindex="-1">8. 📄 ライセンス <a class="header-anchor" href="#_8-📄-ライセンス" aria-label="Permalink to &quot;8. 📄 ライセンス&quot;">​</a></h2><ul><li><strong>Vintage Tuner Stompbox</strong> はフリーウェアとして配布されており、商用・非商用問わず自由にご利用いただけます。</li><li>DSPコアは <strong>MITライセンス</strong> のオープンソースです。</li></ul>`,40)])]))}});export{l as __pageData,d as default};
